python3 -I -c 
import sqlite3,json,os,pathlib
g=pathlib.Path(os.path.expanduser("~"))/".claude/hooks/workflow-guard"
con=sqlite3.connect("file:"+str(g/"state/guard.sqlite3")+"?immutable=1",uri=True);c=con.cursor()
COUNTED=('VALIDATED','RETURNED','LAUNCH_UNVERIFIED','RESERVED')
def run_id(receipt):
    try: return (json.loads(receipt or "{}") or {}).get("run_id")
    except Exception: return None
def wf_root(transcript,receipt):
    try: td=(json.loads(receipt or "{}") or {}).get("transcript_dir")
    except Exception: td=None
    if td: return str(pathlib.Path(td).parent)
    if not transcript: return None
    p=pathlib.Path(transcript); return str(p.parent/p.stem/"subagents"/"workflows")
def inspect(path):
    pend=set();res=set();fail=set();live=0;peak=0;total=0;bad=0
    for line in open(path):
        total+=1
        try: e=json.loads(line)
        except Exception: bad+=1;continue
        key=e.get("key");kind=e.get("type")
        if kind=="started" and key:
            pend.add(key);live+=1
            if live>peak: peak=live
        if kind in ("result","failed") and key: live-=1
        if kind=="result" and key: res.add(key)
        if kind=="failed" and key: fail.add(key)
    pend-=res|fail
    return {"events":total,"started":len(pend|res),"results":len(res),"pending":len(pend),
            "runtime_peak":peak,"running":max(0,live),"malformed":bad}
rows=c.execute("SELECT id,session,peak,transcript,receipt,state FROM launches WHERE state IN (?,?,?,?)",COUNTED).fetchall()
per={};workflows=0;agents=0;detail=[]
for i,sess,peak,tr,rc,state in rows:
    workflows+=1; per[sess]=per.get(sess,0)+1
    rid=run_id(rc); root=wf_root(tr,rc); j=None; m=None
    if rid and root:
        p=pathlib.Path(root)/rid/"journal.jsonl"
        if p.is_file():
            j=str(p); m=inspect(j)
    runv=None if not m else m["running"]
    contrib=int(peak or 0) if runv is None else min(runv,int(peak or 0))
    agents+=contrib
    detail.append({"id":i,"state":state,"declared_peak":peak,"run_id":rid,"journal":j,
                   "journal_summary":m,"running":runv,"contribution":contrib})
print(json.dumps({"workflows":workflows,"workflows_per_program":per,"agents_total":agents,
 "per_row":detail},indent=1))

